#!/usr/bin/env bash
# Proxmox hoszton futtatandó: a javított meres.sh-t bemásolja a meglévő 9001-es VM-be, újrafuttatja a mérést, és összegyűjti az eredményt.
# Futtatás:  nohup bash /root/bench_proxmox_rerun.sh > /root/bench.log 2>&1 &
set -euo pipefail
export LC_ALL=C
VMID=9001; REPS=5
RUNNING=$( (qm list | awk -v id=$VMID 'NR>1 && $3=="running" && $1!=id {print "VM "$1" "$2}'; pct list 2>/dev/null | awk 'NR>1 && $2=="running"{print "CT "$1" "$NF}') || true)
if [ -n "$RUNNING" ]; then echo "Futó vendégek vannak, állítsd le őket:"; echo "$RUNNING"; exit 1; fi
qm status $VMID | grep -q running || { qm start $VMID; sleep 60; }

echo "== Javított meres.sh bemásolása =="
qm guest exec $VMID -- bash -c "echo  | base64 -d > /root/meres.sh && chmod +x /root/meres.sh && rm -rf /root/KESZ /root/eredmenyek /root/meres.log" >/dev/null
echo "== Mérés indítása (kb. 45 perc) =="
qm guest exec $VMID --timeout 0 -- bash -c "setsid nohup bash -c 'cd /root && ./meres.sh proxmox $REPS > /root/meres.log 2>&1; touch /root/KESZ' >/dev/null 2>&1 </dev/null &" >/dev/null

for i in $(seq 1 90); do
  sleep 60
  if qm guest exec $VMID -- test -f /root/KESZ 2>/dev/null | grep -q '"exitcode" : 0'; then echo "Kész."; break; fi
  echo "  $(date +%H:%M) még fut..."
done

echo "== Eredmények összegyűjtése =="
qm guest exec $VMID --timeout 60 -- bash -c 'cd /root && tar czf - eredmenyek meres.log | base64 -w0' \
  | python3 -c 'import json,sys,base64; open("/root/bench_results_proxmox.tar.gz","wb").write(base64.b64decode(json.load(sys.stdin)["out-data"]))'
rm -rf /root/eredmenyek; tar xzf /root/bench_results_proxmox.tar.gz -C /root
echo "Sorok száma a CSV-ben: $(cat /root/eredmenyek/proxmox_*/eredmenyek.csv | wc -l) (várt: 41)"
tail -n 3 /root/meres.log 2>/dev/null || true
echo "Mentve: /root/bench_results_proxmox.tar.gz"
